import numpy as np,json
m=json.load(open('/app/output/contact/meta.json'))
def ray(cam,u,v):
 c=m['cameras'][cam];K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl']);d=np.array([(u-K[0,2])/K[0,0],-(v-K[1,2])/K[1,1],-1.]);d=T[:3,:3]@d;d/=np.linalg.norm(d);return T[:3,3],d
def tri(a,b):
 o1,d1=ray(*a);o2,d2=ray(*b);A=np.stack([d1,-d2],axis=1);t=np.linalg.lstsq(A,o2-o1,rcond=None)[0];p1=o1+t[0]*d1;p2=o2+t[1]*d2;return (p1+p2)/2,np.linalg.norm(p1-p2)
for a,b in [ (('front',166,132),('oblique',184,128)),(('front',155,101),('oblique',170,114)),(('front',159,114),('oblique',170,114)),(('front',178,113),('oblique',183,108)) ]:
 print(a,b,tri(a,b))

